دالة ضغط_التكرار(سلسلة) {
    متغير مضغوط = ""
    متغير الحالي = سلسلة[٠]
    متغير عداد = ١
    من_أجل (ي من ١ إلى طول(سلسلة)) {
        إذا (سلسلة[ي] == الحالي) {
            عداد = عداد + ١
        } وإلا {
            مضغوط = مضغوط + الحالي + عداد
            الحالي = سلسلة[ي]
            عداد = ١
        }
    }
    مضغوط = مضغوط + الحالي + عداد
    ارجع مضغوط
}

